class Solution {public long solve(int[][] rectangles){TreeSet<Integer> set=new TreeSet<>();for(int[] r:rectangles){set.add(r[0]);set.add(r[2]);}Integer[] xs=set.toArray(new Integer[0]);long total=0;for(int i=1;i<xs.length;i++){ArrayList<int[]> intervals=new ArrayList<>();for(int[] r:rectangles)if(r[0]<=xs[i-1]&&r[2]>=xs[i])intervals.add(new int[]{r[1],r[3]});intervals.sort((a,b)->Integer.compare(a[0],b[0]));long height=0,end=Long.MIN_VALUE;for(int[] p:intervals){if(p[1]<=end)continue;height+=(long)p[1]-Math.max((long)p[0],end);end=p[1];}total+=((long)xs[i]-xs[i-1])*height;}return total;}}